def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    op_c = 0
    for _, o in history:
        if o == 'C':
            op_c += 1
    op_d = n - op_c

    last_m, last_o = history[-1]

    if op_c == 0:
        return 'D'

    run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            run += 1
        else:
            break

    if last_o == 'D':
        if run >= 2:
            if run == 2 and last_m == 'D' and op_d * 4 <= n * 3:
                return 'C'
            return 'D'

        if op_d * 3 > n:
            return 'D'

        if last_m == 'D':
            return 'C'

        if n >= 2 and history[-2][0] == 'D' and op_d * 3 <= n:
            return 'C'

        return 'D'

    if last_m == 'D':
        return 'C'

    if n >= 95 and op_d > 0 and op_c * 5 >= n * 4:
        if rng.random() < 0.15:
            return 'D'
        return 'C'

    if op_d * 2 > n:
        return 'D'

    return 'C'
